#!/usr/bin/env python3
"""Build the self-contained D0 0.5B versus sanitized 8B checkpoint report."""

from __future__ import annotations

import argparse
import json
from pathlib import Path


HERE = Path(__file__).resolve().parent
ROOT = HERE.parent
DEFAULT_DATA = ROOT / "D0_0P5B_VS_FULL8_NATIVE_GREEK_3CP_20260814.data.json"
DEFAULT_CONTRACT = HERE / "FULL8_VS_0P5B.data.json"
DEFAULT_OUTPUT = HERE / "D0_0P5B_VS_FULL8_CHECKPOINTS.html"


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--data", type=Path, default=DEFAULT_DATA)
    parser.add_argument("--contract", type=Path, default=DEFAULT_CONTRACT)
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    data = json.loads(args.data.read_text())
    contract = json.loads(args.contract.read_text())["contract"]
    if data.get("schema_version") != "apertus_d0_0p5b_vs_full8_native_greek_3cp_v1":
        raise ValueError("unexpected comparison schema")
    if data.get("status") != "completed" or len(data.get("benchmarks", [])) != 10:
        raise ValueError("comparison is incomplete")
    data["training_contract"] = contract
    payload = json.dumps(data, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")
    html = TEMPLATE.replace("__REPORT_DATA__", payload)
    args.output.write_text(html)
    print(json.dumps({"ok": True, "output": str(args.output), "bytes": args.output.stat().st_size}))
    return 0


